namespace A18.Realtime.Api;

internal static class SwingUi
{
    public const string Html = """
<!doctype html>
<html lang="zh-Hant">
<head>
<meta charset="utf-8">
<meta name="viewport" content="width=device-width,initial-scale=1">
<title>A18_2 K線波段觀察</title>
<style>
:root{color-scheme:dark;--bg:#0b111b;--panel:#121c2a;--line:#27364b;--text:#dbe7f5;--muted:#8191a8;--up:#ff5f6d;--down:#36d6a0;--accent:#54a8ff;--candidate:#ffc857}
*{box-sizing:border-box}body{margin:0;background:var(--bg);color:var(--text);font:13px/1.45 system-ui,"Microsoft JhengHei",sans-serif}
header{display:flex;align-items:center;justify-content:space-between;gap:16px;padding:12px 18px;border-bottom:1px solid var(--line);background:#0f1825;position:sticky;top:0;z-index:2}h1{margin:0;font-size:17px}.tag{font-size:10px;padding:2px 6px;border-radius:3px;background:#245b8a}.controls{display:flex;gap:10px;align-items:center;flex-wrap:wrap}.switch{display:inline-flex;align-items:center;gap:7px;cursor:pointer}.switch input{display:none}.slider{width:34px;height:19px;border-radius:12px;background:#33445a;position:relative;transition:.2s}.slider:after{content:"";position:absolute;width:15px;height:15px;left:2px;top:2px;border-radius:50%;background:#fff;transition:.2s}.switch input:checked+.slider{background:#178bd4}.switch input:checked+.slider:after{transform:translateX(15px)}label{color:var(--muted)}input,select,button{margin-left:4px;border:1px solid var(--line);border-radius:4px;background:#0b1420;color:var(--text);padding:6px 8px}button{cursor:pointer;background:#1769aa;border-color:#2787d5;font-weight:700}main{padding:12px 18px 24px;max-width:1800px;margin:auto}.summary{display:grid;grid-template-columns:repeat(7,minmax(110px,1fr));gap:8px}.summary>div{background:var(--panel);border:1px solid var(--line);padding:8px 10px}.summary span{display:block;color:var(--muted);font-size:11px}.summary strong{font-size:15px;font-variant-numeric:tabular-nums}.panel{border:1px solid var(--line);background:var(--panel)}.chart-panel{height:520px;position:relative;margin-top:10px}canvas{width:100%;height:100%;display:block;cursor:crosshair}.chart-tooltip{position:fixed;z-index:9999;display:none;pointer-events:none;min-width:205px;padding:9px 11px;border-radius:8px;background:rgba(3,10,19,.96);border:1px solid #35506f;color:#eef5ff;font:12px/1.5 system-ui,"Microsoft JhengHei",sans-serif;box-shadow:0 8px 25px rgba(0,0,0,.35);white-space:pre-line}#status{min-height:20px;color:var(--muted);margin:8px 1px}.error{color:#ff8993!important}.candidate{color:var(--candidate)}.table-panel{margin-top:12px}.scroll{max-height:260px;overflow:auto}table{width:100%;border-collapse:collapse;font-variant-numeric:tabular-nums}th,td{padding:6px 9px;border-bottom:1px solid #202e40;white-space:nowrap;text-align:right}th{position:sticky;top:0;background:#172336;color:#9caec4;font-size:11px}th:first-child,td:first-child{text-align:left}.up{color:var(--up)}.down{color:var(--down)}.empty{text-align:center!important;color:var(--muted);padding:22px}@media(max-width:1000px){header{align-items:flex-start;flex-direction:column}.summary{grid-template-columns:repeat(3,1fr)}.chart-panel{height:400px}}
</style>
</head>
<body>
<header>
  <div style="display:flex;gap:10px;align-items:center"><h1>A18_2 · K線波段轉折觀察</h1><span class="tag">LIVE / HISTORY</span></div>
  <form id="controls" class="controls">
    <label>股票 <input id="symbol" value="2330" maxlength="12"></label>
    <button type="button" id="prevDay">← 上一日</button>
    <label>日期 <input id="date" type="date"></label>
    <button type="button" id="nextDay">下一日 →</button>
    <label>K線 <select id="interval"><option value="1">1秒</option><option value="5" selected>5秒</option><option value="60">1分</option><option value="300">5分</option></select></label>
    <label>反轉 <select id="threshold"><option value="0.003">0.3%</option><option value="0.005">0.5%</option><option value="0.008">0.8%</option><option value="0.01" selected>1.0%</option><option value="0.015">1.5%</option><option value="0.02">2.0%</option></select></label>
    <label class="switch" title="以當日開盤為 0%，將加權指數 IX0001 疊加在主圖"><input id="overlay" type="checkbox"><span class="slider"></span><span>加權指數</span></label>
    <button type="submit">載入 / 更新</button>
    <label><input id="auto" type="checkbox" checked> 5秒自動更新</label>
  </form>
</header>
<main>
  <section class="summary">
    <div><span>股票</span><strong id="sSymbol">—</strong></div>
    <div><span>日期</span><strong id="sDate">—</strong></div>
    <div><span>最新價</span><strong id="sPrice">—</strong></div>
    <div><span>K棒數</span><strong id="sBars">—</strong></div>
    <div><span>已確認轉折</span><strong id="sTurns">—</strong></div>
    <div><span>候選轉折</span><strong id="sCandidate" class="candidate">—</strong></div>
    <div><span>資料狀態</span><strong id="sState">—</strong></div>
  </section>
  <p id="status">準備載入。</p>
  <section class="panel chart-panel"><canvas id="chart"></canvas></section>
  <div id="chartTooltip" class="chart-tooltip"></div>
  <section class="panel table-panel"><div class="scroll"><table><thead><tr><th>波段</th><th>起訖時間</th><th>起訖價</th><th>方向</th><th>漲跌幅</th><th>Retracement</th></tr></thead><tbody id="segments"><tr><td colspan="6" class="empty">尚無波段</td></tr></tbody></table></div></section>
</main>
<script>
(()=>{'use strict';const $=id=>document.getElementById(id);const state={bars:[],indexBars:[],turns:[],candidate:null,timer:null,hoverIndex:null,geometry:null};
const fmtP=n=>Number(n).toLocaleString('zh-TW',{maximumFractionDigits:4});const fmtT=s=>new Date(s).toLocaleTimeString('zh-TW',{hour12:false,hour:'2-digit',minute:'2-digit',second:'2-digit'});
function zigzag(bars,th){if(!bars.length)return{turns:[],candidate:null};const pts=bars.map(b=>({time:b.startTime,price:Number(b.close)}));let dir=0,ext=pts[0],hi=pts[0],lo=pts[0];const turns=[];for(let i=1;i<pts.length;i++){const p=pts[i];if(dir===0){if(p.price>=hi.price)hi=p;if(p.price<=lo.price)lo=p;if((hi.price-p.price)/hi.price>=th){turns.push({...hi,type:'H'});dir=-1;ext=p}else if((p.price-lo.price)/lo.price>=th){turns.push({...lo,type:'L'});dir=1;ext=p}}else if(dir===1){if(p.price>=ext.price)ext=p;else if((ext.price-p.price)/ext.price>=th){turns.push({...ext,type:'H'});dir=-1;ext=p}}else{if(p.price<=ext.price)ext=p;else if((p.price-ext.price)/ext.price>=th){turns.push({...ext,type:'L'});dir=1;ext=p}}}let h=0,l=0;return{turns:turns.map(x=>({...x,label:x.type==='H'?`H${++h}`:`L${++l}`})),candidate:dir===0?null:{...ext,type:dir===1?'H':'L'}}}
function renderTable(){const rows=[];for(let i=1;i<state.turns.length;i++){const a=state.turns[i-1],b=state.turns[i],diff=b.price-a.price,prev=rows.at(-1);rows.push({a,b,diff,abs:Math.abs(diff),pct:diff/a.price*100,retrace:prev&&Math.sign(diff)!==Math.sign(prev.diff)&&prev.abs>0?Math.abs(diff)/prev.abs*100:null})}$('segments').innerHTML=rows.length?rows.map(x=>`<tr><td>${x.a.label} → ${x.b.label}</td><td>${fmtT(x.a.time)} → ${fmtT(x.b.time)}</td><td>${fmtP(x.a.price)} → ${fmtP(x.b.price)}</td><td class="${x.diff>=0?'up':'down'}">${x.diff>=0?'上漲':'下跌'}</td><td class="${x.diff>=0?'up':'down'}">${x.pct>=0?'+':''}${x.pct.toFixed(2)}%</td><td>${x.retrace==null?'—':x.retrace.toFixed(1)+'%'}</td></tr>`).join(''):'<tr><td colspan="6" class="empty">尚無足夠已確認轉折</td></tr>'}
function draw(){const cv=$('chart'),r=cv.getBoundingClientRect(),dpr=devicePixelRatio||1;cv.width=Math.max(1,r.width*dpr);cv.height=Math.max(1,r.height*dpr);const c=cv.getContext('2d');c.scale(dpr,dpr);const bars=state.bars,w=r.width,h=r.height,p={l:64,r:18,t:20,b:32};c.clearRect(0,0,w,h);if(!bars.length){c.fillStyle='#8191a8';c.fillText('此日期尚無 K 線資料',p.l,p.t+15);return}const lo=Math.min(...bars.map(b=>Number(b.low))),hi=Math.max(...bars.map(b=>Number(b.high))),rg=hi-lo||Math.max(1,hi*.001),min=lo-rg*.08,max=hi+rg*.08;const y=v=>p.t+(max-v)/(max-min)*(h-p.t-p.b);const cw=(w-p.l-p.r)/Math.max(1,bars.length);state.geometry={w,h,p,cw,y};c.font='11px system-ui';c.strokeStyle='#27364b';c.fillStyle='#8191a8';for(let i=0;i<=5;i++){const yy=p.t+i*(h-p.t-p.b)/5,v=max-i*(max-min)/5;c.beginPath();c.moveTo(p.l,yy);c.lineTo(w-p.r,yy);c.stroke();c.fillText(fmtP(v),4,yy+4)}bars.forEach((b,i)=>{const x=p.l+(i+.5)*cw,o=Number(b.open),cl=Number(b.close),hh=Number(b.high),ll=Number(b.low),up=cl>=o;c.strokeStyle=up?'#ff5f6d':'#36d6a0';c.fillStyle=c.strokeStyle;c.beginPath();c.moveTo(x,y(hh));c.lineTo(x,y(ll));c.stroke();const top=Math.min(y(o),y(cl)),bh=Math.max(1,Math.abs(y(o)-y(cl)));c.fillRect(x-Math.max(1,cw*.28),top,Math.max(2,cw*.56),bh)});if($('overlay').checked&&state.indexBars.length){const ib=state.indexBars.filter(b=>Number(b.close)>0);if(ib.length){const base=Number(ib[0].close);const pcts=ib.map(b=>(Number(b.close)/base-1)*100),plo=Math.min(...pcts),phi=Math.max(...pcts),pr=(phi-plo)||1,pmin=plo-pr*.08,pmax=phi+pr*.08,iy=v=>p.t+(pmax-v)/(pmax-pmin)*(h-p.t-p.b);c.save();c.strokeStyle='#ffc13d';c.fillStyle='#ffc13d';c.lineWidth=1.6;c.beginPath();let started=false;ib.forEach(b=>{const t=new Date(b.startTime).getTime(),i=bars.findIndex(x=>new Date(x.startTime).getTime()>=t);if(i<0)return;const x=p.l+(i+.5)*cw,yy=iy((Number(b.close)/base-1)*100);started?c.lineTo(x,yy):c.moveTo(x,yy);started=true});c.stroke();c.font='11px system-ui';for(let i=0;i<=4;i++){const v=pmax-i*(pmax-pmin)/4,yy=iy(v);c.fillText(`${v>=0?'+':''}${v.toFixed(2)}%`,w-55,yy+4)}c.fillText('IX0001',w-65,p.t+10);c.restore()}}if(state.turns.length){c.lineWidth=1.5;c.strokeStyle='#f5f7ff';c.beginPath();state.turns.forEach((t,i)=>{const bi=bars.findIndex(b=>b.startTime===t.time);if(bi<0)return;const x=p.l+(bi+.5)*cw,yy=y(t.price);i?c.lineTo(x,yy):c.moveTo(x,yy)});c.stroke();state.turns.forEach(t=>{const bi=bars.findIndex(b=>b.startTime===t.time);if(bi<0)return;const x=p.l+(bi+.5)*cw,yy=y(t.price);c.fillStyle=t.type==='H'?'#ff5f6d':'#36d6a0';c.beginPath();c.arc(x,yy,4,0,Math.PI*2);c.fill();c.fillText(`${t.label} ${fmtP(t.price)}`,Math.min(w-90,x+5),t.type==='H'?yy-7:yy+15)})}if(state.candidate){const bi=bars.findIndex(b=>b.startTime===state.candidate.time);if(bi>=0){const x=p.l+(bi+.5)*cw,yy=y(state.candidate.price);const last=state.turns.at(-1);if(last){const li=bars.findIndex(b=>b.startTime===last.time);if(li>=0){const lx=p.l+(li+.5)*cw,ly=y(last.price);c.save();c.strokeStyle='#ffc857';c.lineWidth=1.5;c.setLineDash([6,4]);c.beginPath();c.moveTo(lx,ly);c.lineTo(x,yy);c.stroke();c.restore()}}c.strokeStyle='#ffc857';c.setLineDash([4,3]);c.beginPath();c.arc(x,yy,6,0,Math.PI*2);c.stroke();c.setLineDash([]);c.fillStyle='#ffc857';c.fillText(`${state.candidate.type}? ${fmtP(state.candidate.price)}`,Math.min(w-90,x+5),state.candidate.type==='H'?yy-7:yy+15)}}if(Number.isInteger(state.hoverIndex)&&bars[state.hoverIndex]){const b=bars[state.hoverIndex],x=p.l+(state.hoverIndex+.5)*cw,yy=y(Number(b.close));c.save();c.strokeStyle='rgba(225,236,246,.78)';c.lineWidth=1;c.setLineDash([5,4]);c.beginPath();c.moveTo(x,p.t);c.lineTo(x,h-p.b);c.moveTo(p.l,yy);c.lineTo(w-p.r,yy);c.stroke();c.setLineDash([]);c.fillStyle='#fff';c.beginPath();c.arc(x,yy,3.5,0,Math.PI*2);c.fill();c.restore()}}
function recompute(payload){state.bars=payload.bars||[];const z=zigzag(state.bars,+$('threshold').value);state.turns=z.turns;state.candidate=z.candidate;$('sSymbol').textContent=payload.name?`${payload.symbol} ${payload.name}`:payload.symbol;$('sDate').textContent=payload.tradeDate;$('sPrice').textContent=state.bars.length?fmtP(state.bars.at(-1).close):'—';$('sBars').textContent=state.bars.length;$('sTurns').textContent=state.turns.length;$('sCandidate').textContent=state.candidate?`${state.candidate.type}? ${fmtP(state.candidate.price)} @ ${fmtT(state.candidate.time)}`:'—';$('sState').textContent=payload.dataState||'—';renderTable();draw()}
async function load(){const symbol=$('symbol').value.trim().toUpperCase(),date=$('date').value,interval=$('interval').value;if(!symbol||!date)return;$('status').textContent=`載入 ${symbol} ${date}…`;$('status').className='';try{const mainUrl=`/api/bars/${encodeURIComponent(symbol)}?date=${encodeURIComponent(date)}&interval=${interval}`;const indexUrl=`/api/bars/IX0001?date=${encodeURIComponent(date)}&interval=${interval}`;const [r,ir]=await Promise.all([fetch(mainUrl,{cache:'no-store'}),$('overlay').checked&&symbol!=='IX0001'?fetch(indexUrl,{cache:'no-store'}):Promise.resolve(null)]);if(ir&&ir.ok){try{state.indexBars=(await ir.json()).bars||[]}catch{state.indexBars=[]}}else state.indexBars=[];const text=await r.text();let j={};try{j=text?JSON.parse(text):{}}catch{throw new Error(`HTTP ${r.status} 回傳非 JSON`)}if(!r.ok)throw new Error(j.error||`HTTP ${r.status}`);recompute(j);$('status').textContent=j.hasData?`已載入 ${j.bars.length} 根 K；資料來源：${j.source||'A18_2 LIVE'}。`:`${date} 目前尚無資料（NO_DATA_YET），不會切換到其他日期。`}catch(e){state.bars=[];state.turns=[];state.candidate=null;state.hoverIndex=null;$('sDate').textContent=date;$('sPrice').textContent='—';$('sBars').textContent='0';$('sTurns').textContent='0';$('sCandidate').textContent='—';$('sState').textContent='ERROR';renderTable();draw();$('status').textContent='載入失敗：'+e.message;$('status').className='error'}}
const chart=$('chart'),tip=$('chartTooltip');chart.addEventListener('mousemove',e=>{const g=state.geometry;if(!g||!state.bars.length)return;const r=chart.getBoundingClientRect(),mx=e.clientX-r.left;const raw=(mx-g.p.l)/Math.max(0.000001,g.cw)-.5;const i=Math.max(0,Math.min(state.bars.length-1,Math.round(raw)));state.hoverIndex=i;draw();const b=state.bars[i],up=Number(b.close)>=Number(b.open);let indexTip='';if($('overlay').checked&&state.indexBars.length){const bt=new Date(b.startTime).getTime();let ib=null,best=Infinity;for(const x of state.indexBars){const d=Math.abs(new Date(x.startTime).getTime()-bt);if(d<best){best=d;ib=x}}if(ib&&best<=Math.max(1000,+$('interval').value*1000)){const base=Number(state.indexBars.find(x=>Number(x.close)>0)?.close||0),iv=Number(ib.close),pct=base>0?(iv/base-1)*100:null;indexTip=`\n────────────\nIX0001 ${fmtP(iv)}${pct==null?'':`   ${pct>=0?'+':''}${pct.toFixed(2)}%`}`}}tip.textContent=`${fmtT(b.startTime)}\nO ${fmtP(b.open)}   H ${fmtP(b.high)}\nL ${fmtP(b.low)}   C ${fmtP(b.close)}\nV ${Number(b.volume).toLocaleString('zh-TW')}   ticks ${b.tickCount}${indexTip}`;tip.style.display='block';tip.style.left=`${Math.min(innerWidth-230,e.clientX+14)}px`;tip.style.top=`${Math.min(innerHeight-125,e.clientY+14)}px`;tip.style.borderColor=up?'#8d4a53':'#2f7765'});chart.addEventListener('mouseleave',()=>{state.hoverIndex=null;tip.style.display='none';draw()});$('controls').addEventListener('submit',e=>{e.preventDefault();load()});$('threshold').addEventListener('change',()=>state.bars.length&&recompute({symbol:$('symbol').value.trim().toUpperCase(),tradeDate:$('date').value,dataState:'AVAILABLE',bars:state.bars}));$('interval').addEventListener('change',load);$('date').addEventListener('change',()=>{savePrefs();load()});$('auto').addEventListener('change',()=>{clearInterval(state.timer);state.timer=$('auto').checked?setInterval(load,5000):null});window.addEventListener('resize',draw);
const storageKey='a18_swing_preferences_v1';
function savePrefs(){try{localStorage.setItem(storageKey,JSON.stringify({symbol:$('symbol').value.trim().toUpperCase(),interval:$('interval').value,date:$('date').value,overlay:$('overlay').checked}))}catch{}}
function shiftDay(delta){const v=$('date').value;if(!v)return;const d=new Date(v+'T12:00:00');d.setDate(d.getDate()+delta);$('date').value=`${d.getFullYear()}-${String(d.getMonth()+1).padStart(2,'0')}-${String(d.getDate()).padStart(2,'0')}`;savePrefs();load()}
$('prevDay').addEventListener('click',()=>shiftDay(-1));$('nextDay').addEventListener('click',()=>shiftDay(1));$('symbol').addEventListener('change',savePrefs);$('interval').addEventListener('change',savePrefs);$('overlay').addEventListener('change',()=>{savePrefs();load()});
let prefs={};try{prefs=JSON.parse(localStorage.getItem(storageKey)||'{}')}catch{}if(prefs.symbol)$('symbol').value=prefs.symbol;if(['1','5','60','300'].includes(String(prefs.interval)))$('interval').value=String(prefs.interval);else $('interval').value='5';$('overlay').checked=Boolean(prefs.overlay);
const n=new Date();const today=`${n.getFullYear()}-${String(n.getMonth()+1).padStart(2,'0')}-${String(n.getDate()).padStart(2,'0')}`;$('date').value=/^\d{4}-\d{2}-\d{2}$/.test(String(prefs.date||''))?prefs.date:today;state.timer=setInterval(load,5000);load();})();
</script>
</body>
</html>
""";
}
